package de.example.reports.util;
import net.kyori.adventure.text.Component; import net.kyori.adventure.text.minimessage.MiniMessage; import org.bukkit.command.CommandSender; import org.bukkit.configuration.file.FileConfiguration; import java.util.Map;
public final class Messages { private FileConfiguration config; private final MiniMessage mm=MiniMessage.miniMessage(); public Messages(FileConfiguration c){config=c;} public void reload(FileConfiguration c){config=c;} public void send(CommandSender s,String key){send(s,key,Map.of());} public void send(CommandSender s,String key,Map<String,String> values){String text=config.getString("messages.prefix","")+config.getString("messages."+key,"<red>Missing message: "+key+"</red>"); for(var e:values.entrySet()) text=text.replace("%"+e.getKey()+"%",e.getValue()); s.sendMessage(mm.deserialize(text));} public Component component(String text){return mm.deserialize(text);} }
